/* KAVITY shared page scripts: mega menu, back-to-top, site search (index incl. every catalogue product) */

var html=document.documentElement;

var burger=document.getElementById('burger'), nav=document.getElementById('nav');
function setNav(o){ nav.classList.toggle('open',o); burger.setAttribute('aria-expanded',o); html.classList.toggle('nav-open',o); }
burger.addEventListener('click',function(){ setNav(!nav.classList.contains('open')); });
document.addEventListener('keydown',function(e){ if(e.key==='Escape'&&nav.classList.contains('open')){ setNav(false); burger.focus(); } });
nav.addEventListener('click',function(e){ var a=e.target.closest&&e.target.closest('a[href]'); if(a&&!a.matches('.nav-mm > a,[aria-haspopup]')) setNav(false); });
window.matchMedia('(min-width:921px)').addEventListener('change',function(m){ if(m.matches) setNav(false); });

document.querySelectorAll('.filters button').forEach(function(b){
  b.addEventListener('click',function(){
    document.querySelectorAll('.filters button').forEach(function(x){x.setAttribute('aria-pressed','false')});
    b.setAttribute('aria-pressed','true');
    var m=b.dataset.market;
    document.querySelectorAll('.proj').forEach(function(p){
      p.style.display = (m==='all'||p.dataset.market===m)?'':'none';
    });
  });
});


(function(){
  var bar=document.createElement('div'); bar.className='progress'; document.body.appendChild(bar);
  var hdr=document.querySelector('header'), max=1, small=null, ticking=false;
  function measure(){ max=Math.max(1,document.documentElement.scrollHeight-window.innerHeight); }
  function paint(){ ticking=false; var y=window.scrollY;
    bar.style.setProperty('--kv-p',Math.min(1,y/max).toFixed(4));
    var s=y>60; if(hdr&&s!==small){ small=s; hdr.classList.toggle('small',s); } }
  var lastY=window.scrollY, idle=0;
  function fab(){ var y=window.scrollY, d=y-lastY; lastY=y;
    if(Math.abs(d)>6) html.classList.toggle('kv-fab-hide', d>0 && y>400 && !html.classList.contains('nav-open'));
    if(window.innerWidth>=600){ clearTimeout(idle); idle=setTimeout(function(){ html.classList.remove('kv-fab-hide'); },900); } }
  function onScroll(){ fab(); if(!ticking){ ticking=true; requestAnimationFrame(paint); } }
  measure(); paint();
  window.addEventListener('scroll',onScroll,{passive:true});
  window.addEventListener('resize',function(){ measure(); onScroll(); });
  window.addEventListener('load',measure);
  if('ResizeObserver' in window) new ResizeObserver(measure).observe(document.body);
})();

(function(){
  var sel='.sec > .wrap > *, .feats-card, .lines, .grid-proj, .cards, .cat-grid, .cgrid, .compare, .why-grid, .uses';
  var items=document.querySelectorAll(sel);
  if(!('IntersectionObserver' in window)) return;
  var io=new IntersectionObserver(function(es){
    es.forEach(function(e,i){
      if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  },{threshold:0,rootMargin:'0px 0px -60px 0px'});
  items.forEach(function(el,i){
    el.classList.add('reveal');
    el.style.transitionDelay=(Math.min(i%4,3)*70)+'ms';
    io.observe(el);
  });
})();


(function(){
  var st=document.querySelectorAll('.stat'); if(!st.length||!('IntersectionObserver' in window)) return;
  var io=new IntersectionObserver(function(es){
    es.forEach(function(e){ if(e.isIntersecting){e.target.classList.add('in'); io.unobserve(e.target);} });
  },{threshold:.4});
  st.forEach(function(x){io.observe(x)});
})();


(function(){
  var w=document.getElementById('navMM'); if(!w) return;
  var tiles=w.querySelectorAll('.mm-tile'), panels=w.querySelectorAll('.mm-panel'), t=null;
  function show(f){
    tiles.forEach(function(x){x.classList.toggle('on',x.dataset.fam===f)});
    panels.forEach(function(x){x.classList.toggle('on',x.dataset.fam===f)});
  }
  tiles.forEach(function(x){
    x.addEventListener('mouseenter',function(){show(x.dataset.fam)});
    x.addEventListener('click',function(e){e.preventDefault();show(x.dataset.fam)});
    x.addEventListener('focus',function(){show(x.dataset.fam)});
  });
  function open(){clearTimeout(t); w.classList.add('open')}
  function close(){t=setTimeout(function(){w.classList.remove('open')},220)}
  if(window.matchMedia('(min-width:1081px)').matches){
    w.addEventListener('mouseenter',open);
    w.addEventListener('mouseleave',close);
    w.querySelector('.has-mm').addEventListener('focus',open);
  }
  w.querySelector('.has-mm').addEventListener('click',function(e){
    if(window.matchMedia('(max-width:1080px)').matches){e.preventDefault(); w.classList.toggle('open');}
  });
  document.addEventListener('keydown',function(e){ if(e.key==='Escape') w.classList.remove('open') });
})();


(function(){
  var t=document.getElementById('toTop'); if(!t) return;
  addEventListener('scroll',function(){t.classList.toggle('show',scrollY>700)},{passive:true});
  t.addEventListener('click',function(){scrollTo({top:0,behavior:'smooth'})});
})();


