  function nz(t){return String(t).toLowerCase().replace(/[\u064B-\u0652\u0670\u0640]/g,'').replace(/[\u0623\u0625\u0622]/g,'\u0627').replace(/\u0649/g,'\u064A').replace(/\u0629/g,'\u0647').replace(/\u0624/g,'\u0648').replace(/\u0626/g,'\u064A').replace(/\u00a0/g,' ')}
  var ov=document.getElementById('sov'), q=document.getElementById('sq'), res=document.getElementById('sres');
  if(!ov||!q||!res) return;
  function open(){ov.hidden=false;q.value='';render('');setTimeout(function(){q.focus()},30)}
  function close(){ov.hidden=true}
