/* sub-range chips: on phones scroll the current page's chip into view; keep WhatsApp off the hero */
(function(){
  document.querySelectorAll('.sub-nav').forEach(function(n){ var a=n.querySelector('a.on'); if(a&&n.scrollWidth>n.clientWidth) n.scrollLeft=a.offsetLeft-(n.clientWidth-a.offsetWidth)/2;
    function edge(){ n.classList.toggle('kv-l',n.scrollLeft>2); n.classList.toggle('kv-r',n.scrollLeft+n.clientWidth<n.scrollWidth-2); }
    edge(); n.addEventListener('scroll',edge,{passive:true}); });
  var ph=document.querySelector('.phero');
  if(ph&&'IntersectionObserver' in window&&window.innerWidth<641){
    new IntersectionObserver(function(e){ document.documentElement.classList.toggle('kv-fab-hero',e[0].isIntersecting); },{threshold:.35}).observe(ph);
  }
})();
